/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		propName: "skippedRecordRulesCount",
		value: event.payload.model.layoutQuery.count || 0
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		propName: "listRefresh",
		value: {
			timeStamp: Date.now(),
			background: true
		}
	};
}
